(()=>{
const form=document.querySelector('#catalog-search-form'),input=document.querySelector('#catalog-search'),categories=document.querySelector('.catalog-cards'),results=document.querySelector('#product-results'),count=document.querySelector('#catalog-result-count'),empty=document.querySelector('#catalog-empty'),reset=document.querySelector('#catalog-reset'),more=document.querySelector('#product-more');
const core=CatalogSearch;let index=null,loading=null,queryVersion=0,matches=[],limit=24,timer;
const dialog=document.querySelector('#product-dialog');
function imageUrl(product){return product.image||'https://www.gimaitaly.com/images/prodotti/medium/'+encodeURIComponent(product.code)+'.jpg'}
function openProduct(product){
document.querySelector('#product-title').textContent=product.name;document.querySelector('#product-code').textContent='Codice catalogo '+product.code;document.querySelector('#product-category').textContent=product.category;
const image=document.querySelector('#product-image'),visual=document.querySelector('#product-visual');visual.hidden=false;image.style.opacity='0';image.onload=()=>{image.style.opacity='1'};image.onerror=()=>{visual.hidden=true};image.alt=product.name;image.referrerPolicy='no-referrer';image.src=imageUrl(product);
const specs=document.querySelector('#product-specs');specs.replaceChildren();for(const [label,value] of product.specifications||[]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;specs.append(dt,dd)}specs.hidden=!product.specifications?.length;
document.querySelector('#product-description').textContent=product.description||'Per le caratteristiche tecniche di questo articolo e per informazioni sulla fornitura, contatta Biancamedical indicando il codice prodotto.';
document.querySelector('#product-contact').href='mailto:clementipaolo@libero.it?subject='+encodeURIComponent('Informazioni prodotto '+product.code+' — '+product.name);dialog.showModal()
}
document.querySelector('#product-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
function showCategories(){queryVersion++;results.removeAttribute('aria-busy');categories.hidden=false;results.hidden=true;results.replaceChildren();empty.hidden=true;more.hidden=true;reset.hidden=true;count.textContent='19 categorie disponibili';matches=[]}
function renderProducts(){results.replaceChildren();for(const p of matches.slice(0,limit)){const card=document.createElement('article');card.className='product-card';const code=document.createElement('span');code.className='product-code';code.textContent='COD. '+p.code;const title=document.createElement('h3');title.textContent=p.name;const category=document.createElement('p');category.textContent=p.category;const action=document.createElement('button');action.type='button';action.className='product-open';action.textContent='Vedi prodotto ↗';action.setAttribute('aria-label','Vedi prodotto '+p.name+', codice '+p.code);action.addEventListener('click',()=>openProduct(p));const photo=document.createElement('div');photo.className='product-card-photo';const image=document.createElement('img');image.loading='lazy';image.decoding='async';image.referrerPolicy='no-referrer';image.alt=p.name;image.src=imageUrl(p);image.onerror=()=>{photo.hidden=true};photo.append(image);card.append(photo,code,title,category,action);results.append(card)}more.hidden=matches.length<=limit;if(!more.hidden)more.textContent='Mostra altri prodotti ('+Math.min(24,matches.length-limit)+')'}
function loadProducts(){if(index)return Promise.resolve(index);if(!loading){loading=fetch('prodotti.json',{cache:'no-cache'}).then(response=>{if(!response.ok)throw Error('Prodotti non disponibili');return response.json()}).then(data=>{index=core.prepare(data);return index}).finally(()=>{loading=null})}return loading}
async function runSearch(){const query=input.value.trim();const version=++queryVersion;limit=24;if(!query){showCategories();return}categories.hidden=true;results.hidden=false;results.replaceChildren();results.removeAttribute('aria-busy');empty.hidden=true;more.hidden=true;reset.hidden=false;if(core.normalize(query).length<3){count.textContent='Inserisci almeno 3 caratteri o un codice prodotto.';return}count.textContent='Ricerca prodotti in corso…';results.setAttribute('aria-busy','true');try{const products=await loadProducts();if(version!==queryVersion)return;matches=core.search(products,query);count.textContent=matches.length===1?'1 prodotto trovato':matches.length+' prodotti trovati';empty.hidden=matches.length!==0;renderProducts()}catch(error){if(version!==queryVersion)return;count.textContent='Ricerca momentaneamente non disponibile. Premi la lente per riprovare.'}finally{if(version===queryVersion)results.removeAttribute('aria-busy')}}
form.addEventListener('submit',event=>{event.preventDefault();clearTimeout(timer);runSearch()});input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(runSearch,180)});input.addEventListener('focus',()=>{loadProducts().catch(()=>{})});reset.addEventListener('click',()=>{clearTimeout(timer);input.value='';showCategories();input.focus()});more.addEventListener('click',()=>{limit+=24;renderProducts()});

const button=document.querySelector('#download-catalog'),status=document.querySelector('#catalog-download-status');
let library;
function loadLibrary(){if(window.PDFLib)return Promise.resolve();if(!library)library=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/pdf-lib.min.js';script.onload=resolve;script.onerror=()=>{library=null;script.remove();reject(Error('Impossibile caricare il lettore PDF.'))};document.head.append(script)});return library}
button.addEventListener('click',async()=>{button.disabled=true;button.setAttribute('aria-busy','true');status.textContent='Preparazione del catalogo completo…';let url;
try{await loadLibrary();const response=await fetch('catalogo.json');if(!response.ok)throw Error('Catalogo non disponibile.');const sections=await response.json();const full=await PDFLib.PDFDocument.create();for(let i=0;i<sections.length;i++){status.textContent=`Preparazione del catalogo: sezione ${i+1} di ${sections.length}…`;const result=await fetch(sections[i].file);if(!result.ok)throw Error('Una sezione non è disponibile.');const part=await PDFLib.PDFDocument.load(await result.arrayBuffer());const pages=await full.copyPages(part,part.getPageIndices());pages.forEach(page=>full.addPage(page))}full.setTitle('Biancamedical - Catalogo generale');full.setAuthor('Biancamedical');if(full.getPageCount()!==483)throw Error('Il catalogo non è completo.');const bytes=await full.save();url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download='Biancamedical_Catalogo_Completo.pdf';document.body.append(a);a.click();a.remove();status.textContent='Catalogo pronto: download avviato.';setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){status.textContent='Non è stato possibile preparare il file completo. Puoi scaricare le singole categorie qui sotto.';if(url)URL.revokeObjectURL(url)}finally{button.disabled=false;button.removeAttribute('aria-busy')}});
})();
